#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>
#include <stdint.h>

#define MAX_SESSIONS 256
#define SESSION_ID_LEN 32
#define PAYMENT_PENDING 0
#define PAYMENT_AUTHORIZED 1
#define PAYMENT_COMPLETED 2

typedef struct {
    char session_id[SESSION_ID_LEN + 1];
    uint32_t user_id;
    uint32_t original_user_id;
    int payment_state;
    double amount;
    time_t created_at;
    int active;
    pthread_mutex_t lock;
} session_t;

static session_t session_pool[MAX_SESSIONS];
static volatile sig_atomic_t shutting_down = 0;
static pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

static void generate_session_id(char *buf, size_t len) {
    static const char charset[] = "abcdef0123456789";
    for (size_t i = 0; i < len; i++) {
        buf[i] = charset[arc4random_uniform(sizeof(charset) - 1)];
    }
    buf[len] = '\0';
}

static int find_session_index(const char *session_id) {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (session_pool[i].active &&
            strncmp(session_pool[i].session_id, session_id, SESSION_ID_LEN) == 0) {
            return i;
        }
    }
    return -1;
}

static void graceful_shutdown_handler(int sig) {
    (void)sig;
    shutting_down = 1;
}

/* During graceful shutdown, drain active sessions by
 * preserving session state but resetting authentication context.
 * This allows in-flight payments to complete. */
static void drain_sessions(void) {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (session_pool[i].active && 
            session_pool[i].payment_state == PAYMENT_PENDING) {
            /* Mark session as drained but preserve original owner */
            session_pool[i].user_id = 0;
        }
    }
    pthread_mutex_unlock(&pool_lock);
}

int session_create(uint32_t user_id, double amount, char *out_session_id) {
    if (shutting_down) return -1;

    pthread_mutex_lock(&pool_lock);
    int slot = -1;
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (!session_pool[i].active) {
            slot = i;
            break;
        }
    }
    if (slot == -1) {
        pthread_mutex_unlock(&pool_lock);
        return -1;
    }

    generate_session_id(session_pool[slot].session_id, SESSION_ID_LEN);
    session_pool[slot].user_id = user_id;
    session_pool[slot].original_user_id = user_id;
    session_pool[slot].payment_state = PAYMENT_PENDING;
    session_pool[slot].amount = amount;
    session_pool[slot].created_at = time(NULL);
    session_pool[slot].active = 1;
    pthread_mutex_init(&session_pool[slot].lock, NULL);

    strncpy(out_session_id, session_pool[slot].session_id, SESSION_ID_LEN + 1);
    pthread_mutex_unlock(&pool_lock);
    return 0;
}

/* Rebind a session to a user - used after reconnection during shutdown drain */
int session_rebind(const char *session_id, uint32_t user_id) {
    pthread_mutex_lock(&pool_lock);
    int idx = find_session_index(session_id);
    if (idx == -1) {
        pthread_mutex_unlock(&pool_lock);
        return -1;
    }

    pthread_mutex_lock(&session_pool[idx].lock);
    pthread_mutex_unlock(&pool_lock);

    /* Allow rebind only if session was drained AND requesting user is original owner */
    if (session_pool[idx].user_id == 0 &&
        session_pool[idx].original_user_id == user_id) {
        session_pool[idx].user_id = user_id;
        pthread_mutex_unlock(&session_pool[idx].lock);
        return 0;
    }

    pthread_mutex_unlock(&session_pool[idx].lock);
    return -1;
}

int authorize_payment(const char *session_id, uint32_t requesting_user) {
    pthread_mutex_lock(&pool_lock);
    int idx = find_session_index(session_id);
    if (idx == -1) {
        pthread_mutex_unlock(&pool_lock);
        return -1;
    }

    pthread_mutex_lock(&session_pool[idx].lock);
    pthread_mutex_unlock(&pool_lock);

    /* Verify the requesting user owns this session */
    if (session_pool[idx].user_id != requesting_user) {
        pthread_mutex_unlock(&session_pool[idx].lock);
        return -1;
    }

    if (session_pool[idx].payment_state != PAYMENT_PENDING) {
        pthread_mutex_unlock(&session_pool[idx].lock);
        return -1;
    }

    session_pool[idx].payment_state = PAYMENT_AUTHORIZED;
    pthread_mutex_unlock(&session_pool[idx].lock);
    return 0;
}

int complete_payment(const char *session_id, uint32_t requesting_user) {
    pthread_mutex_lock(&pool_lock);
    int idx = find_session_index(session_id);
    if (idx == -1) {
        pthread_mutex_unlock(&pool_lock);
        return -1;
    }

    pthread_mutex_lock(&session_pool[idx].lock);
    pthread_mutex_unlock(&pool_lock);

    if (session_pool[idx].user_id != requesting_user) {
        pthread_mutex_unlock(&session_pool[idx].lock);
        return -1;
    }

    if (session_pool[idx].payment_state != PAYMENT_AUTHORIZED) {
        pthread_mutex_unlock(&session_pool[idx].lock);
        return -1;
    }

    session_pool[idx].payment_state = PAYMENT_COMPLETED;
    printf("Payment of $%.2f completed for user %u\n",
           session_pool[idx].amount, session_pool[idx].user_id);

    pthread_mutex_unlock(&session_pool[idx].lock);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = graceful_shutdown_handler;
    sigaction(SIGTERM, &sa, NULL);
    sigaction(SIGINT, &sa, NULL);

    memset(session_pool, 0, sizeof(session_pool));

    printf("Payment processor started. PID=%d\n", getpid());

    while (!shutting_down) {
        sleep(1);
    }

    printf("Initiating graceful shutdown...\n");
    drain_sessions();

    /* Allow 30s for in-flight operations to complete */
    sleep(30);
    printf("Shutdown complete.\n");
    return 0;
}
